#let proxy_meta_line(loopback: false) = {
  let data = proxy_data(loopback: loopback)
  let m = data.meta
  text(size: 8pt, fill: gray)[
    Registrado #m.date · servidor #m.host · #m.cpu ·
    #if not loopback { [generador #data.generator.host · #data.generator.cpu ·] }
    Revisión Sibuna #raw(m.git.slice(0, 12)) ·
    Zig #m.zig · BunkerWeb #data.bunkerweb.version ·
    #if data.at("anubis", default: none) != none { [#data.anubis.version ·] }
    #data.load.threads hilos de carga, #data.load.connections conexiones ·
    #data.load.seconds s × #data.load.repetitions rondas, con #data.load.warmup s de calentamiento
  ]
}

